mapper.select:
select e.event_id, e.site_code, e.rule_id, e.order_no, e.amount, e.cum_count, e.cum_amount, e.trigger_time, e.level, e.trigger_point, e.amount_mode, e.currency, e.notify_status, e.notify_reason, e.notify_chats::text as notify_chats, e.notified_at, e.handle_status, e.handle_note, e.handle_by, e.handle_time, e.report_by, e.create_time, r.rule_no, r.rule_name, r.description as rule_description, r.config::text as rule_config, r.enabled as rule_enabled, r.owner_user_id, ou.nick_name as owner_name, coalesce(r.del_flag = '2', false) as rule_deleted, coalesce(nullif(hu.email, ''), hu.user_name, e.handle_by) as handle_by_name from monitor_order_event e left join monitor_rule r on r.rule_id = e.rule_id and r.site_code = e.site_code left join sys_user ou on ou.user_id = r.owner_user_id left join sys_user hu on hu.user_id::text = e.handle_by where 1 = 1
and e.handle_status = #{q.handle}
and e.trigger_time >= #{q.rangeFrom}
and e.trigger_time < #{q.rangeTo}
and e.rule_id in #{v}
and r.owner_user_id in #{v}
order by e.trigger_time desc, e.event_id desc

select count(*)
  from monitor_order_event e
 where e.event_id in #{v}

mapper.update:
update monitor_order_event
   set handle_status = 'done',
       handle_note   = #{note},
       handle_by     = #{by},
       handle_time   = #{now}
 where site_code = #{scope.siteCode}
   and event_id in #{v}

update monitor_order_event
   set notify_status = #{status},
       notify_reason = null,
       notify_chats  = #{chats}::jsonb
       , notified_at = #{at}
 where site_code = #{scope.siteCode}
   and event_id = #{eventId}
